const f = $input.first().json;
const missing = [];
function blank(v) { return v === undefined || v === null || String(v).trim() === ''; }
if (blank(f['Full Name'])) missing.push('Full Name');
if (blank(f['Email'])) missing.push('Email');
if (blank(f['Phone Number'])) missing.push('Phone Number');
if (blank(f['Level of Education'])) missing.push('Level of Education');
if (blank(f['Target Program'])) missing.push('Target Program');
if (blank(f['GPA / CGPA'])) missing.push('GPA / CGPA');
if (blank(f['Percentage'])) missing.push('Percentage');
if (blank(f['Annual Family Income'])) missing.push('Annual Family Income');
if (blank(f['Budget Range'])) missing.push('Budget Range');
if (blank(f['Applying for Financial Aid/Scholarship?'])) missing.push('Applying for Financial Aid/Scholarship?');
return [{ json: Object.assign({}, f, { _missing_fields: missing, _has_missing: missing.length > 0 }) }];

const f = $input.first().json;
const lvl = String(f['Level of Education'] || '');
const prog = String(f['Target Program'] || '').toLowerCase();
// predominant degree: 3 = bachelor, 4 = graduate
let degree = '3';
if (lvl === "Bachelor's" || lvl === "Master's" || lvl === 'PhD' || /(\bms\b|m\.s|master|phd|mba|graduate|msc|m\.eng)/.test(prog)) { degree = '4'; }
return [{ json: Object.assign({}, f, { _degree: degree }) }];

const items = $input.all().map(function(i){ return i.json; });
let results = [];
if (items.length === 1 && items[0] && Array.isArray(items[0].results)) { results = items[0].results; }
else if (items.length === 1 && Array.isArray(items[0])) { results = items[0]; }
else { results = items; }
function money(v){ return (v !== null && v !== undefined && v !== '') ? ('USD ' + Number(v).toLocaleString('en-US') + ' /year') : 'Not reported'; }
const picked = [];
for (let i = 0; i < results.length; i++) {
  if (picked.length >= 10) break;
  const r = results[i] || {};
  const name = r['school.name'];
  if (!name) continue;
  const size = r['latest.student.size'];
  const rate = r['latest.admissions.admission_rate.overall'];
  let website = r['school.school_url'] || '';
  if (website && !/^https?:/i.test(website)) website = 'https://' + website;
  picked.push({
    university_name: name,
    city: r['school.city'] || '',
    state: r['school.state'] || '',
    location: [r['school.city'], r['school.state']].filter(Boolean).join(', '),
    website: website,
    student_count: (size !== null && size !== undefined) ? String(size) : 'Not reported',
    acceptance_rate: (rate !== null && rate !== undefined) ? (Math.round(rate * 1000) / 10) + '%' : 'Not reported',
    sat_scores_reported: r['latest.admissions.sat_scores.overall'] || 'Not reported',
    annual_tuition_fee: money(r['latest.cost.tuition.out_of_state'] || r['latest.cost.tuition.in_state']),
    avg_net_price: money(r['latest.cost.avg_net_price.overall']),
    total_annual_cost: money(r['latest.cost.attendance.academic_year'])
  });
}
return [{ json: { universities: picked, count: picked.length } }];

