const facts = (($('Shortlist Universities').first().json || {}).universities) || [];
const sch = (($('Scholarships & Aid Agent').first().json || {}).output) || {};
const guides = (($('Visa Guide Agent').first().json || {}).output) || {};
const enr = Array.isArray(sch.enrichments) ? sch.enrichments : [];
function norm(s){ return String(s || '').toLowerCase().replace(/[^a-z0-9]/g, ''); }
function findEnr(name){ for (let i=0;i<enr.length;i++){ if (norm(enr[i].university_name) === norm(name)) return enr[i]; } return {}; }
let universities = facts.map(function(f){
  const e = findEnr(f.university_name) || {};
  return {
    university_name: f.university_name,
    location: f.location, city: f.city, state: f.state, website: f.website,
    student_count: f.student_count, acceptance_rate: f.acceptance_rate,
    annual_tuition_fee: f.annual_tuition_fee, avg_net_price: f.avg_net_price, total_annual_cost: f.total_annual_cost,
    program_availability: e.program_availability || '',
    admission_requirements: e.admission_requirements || '',
    gpa_percentage_requirement: e.gpa_percentage_requirement || '',
    application_deadline: e.application_deadline || '',
    sat_requirement: e.sat_requirement || '',
    english_test_requirement: e.english_test_requirement || '',
    application_fee: e.application_fee || '',
    need_based_scholarship: e.need_based_scholarship || '',
    merit_based_scholarship: e.merit_based_scholarship || '',
    international_financial_aid: e.international_financial_aid || '',
    scholarship_tips: e.scholarship_tips || '',
    estimated_out_of_pocket: e.estimated_out_of_pocket || '',
    required_bank_balance: e.required_bank_balance || '',
    source_url: e.source_url || f.website || '',
    data_confidence: e.data_confidence || '',
    university_specific_visa_prep: Array.isArray(e.university_specific_visa_prep) ? e.university_specific_visa_prep : []
  };
});
// Drop SAT-required schools (student has no SAT)
const noSat = universities.filter(function(u){ return !/sat required/i.test(u.sat_requirement || ''); });
if (noSat.length > 0) universities = noSat;
return [{ json: { output: {
  universities: universities,
  overall_target_bank_balance: sch.overall_target_bank_balance || '',
  recommendation_summary: sch.recommendation_summary || '',
  application_guide: guides.application_guide || '',
  visa_guide: guides.visa_guide || '',
  visa_interview_prep: guides.visa_interview_prep || ''
} } }];

const agentOut = $input.first().json.output || {};
const form = $('Lead Intake Form').first().json;
const unis = Array.isArray(agentOut.universities) ? agentOut.universities : [];
const now = new Date().toISOString();
const appG = agentOut.application_guide || '';
const visaG = agentOut.visa_guide || '';
const prep = agentOut.visa_interview_prep || '';
if (!unis.length) {
  return [{ json: { submitted_at: now, full_name: form['Full Name'] || '', email: form['Email'] || '', rank: '', matched_university: '', location: '', university_specific_visa_qa: '', application_guide: appG, visa_guide: visaG, visa_interview_prep: prep } }];
}
return unis.map(function (u, i) {
  u = u || {};
  const visaQA = Array.isArray(u.university_specific_visa_prep) ? u.university_specific_visa_prep : [];
  return { json: {
    submitted_at: now,
    full_name: form['Full Name'] || '',
    email: form['Email'] || '',
    rank: i + 1,
    matched_university: u.university_name || '',
    location: u.location || '',
    university_specific_visa_qa: visaQA.map(function(q){ return 'Q: ' + (q.question || '') + ' | A: ' + (q.sample_answer || ''); }).join('  ||  '),
    application_guide: appG,
    visa_guide: visaG,
    visa_interview_prep: prep
  } };
});

const agentOut = $input.first().json.output || {};
const form = $('Lead Intake Form').first().json;
const unis = Array.isArray(agentOut.universities) ? agentOut.universities : [];
let rows = '';
for (let i = 0; i < unis.length; i++) {
  const u = unis[i] || {};
  rows += '<h3>' + (i + 1) + '. ' + (u.university_name || 'University') + '</h3>';
  rows += '<ul>';
  rows += '<li><b>Location:</b> ' + (u.location || 'N/A') + '</li>';
  rows += '<li><b>Website:</b> ' + (u.website ? ('<a href="' + u.website + '">' + u.website + '</a>') : 'N/A') + '</li>';
  rows += '<li><b>Number of Students:</b> ' + (u.student_count || 'N/A') + '</li>';
  rows += '<li><b>Acceptance Rate:</b> ' + (u.acceptance_rate || 'N/A') + '</li>';
  rows += '<li><b>Program:</b> ' + (u.program_availability || 'N/A') + '</li>';
  rows += '<li><b>GPA / Percentage Requirement:</b> ' + (u.gpa_percentage_requirement || 'N/A') + '</li>';
  rows += '<li><b>SAT Requirement:</b> ' + (u.sat_requirement || 'N/A') + '</li>';
  rows += '<li><b>English Test Requirement:</b> ' + (u.english_test_requirement || 'N/A') + '</li>';
  rows += '<li><b>Application Deadline:</b> ' + (u.application_deadline || 'N/A') + '</li>';
  rows += '<li><b>Application Fee:</b> ' + (u.application_fee || 'N/A') + '</li>';
  rows += '<li><b>Annual Tuition Fee:</b> ' + (u.annual_tuition_fee || 'N/A') + '</li>';
  rows += '<li><b>Average Net Price:</b> ' + (u.avg_net_price || 'N/A') + '</li>';
  rows += '<li><b>Total Annual Cost:</b> ' + (u.total_annual_cost || 'N/A') + '</li>';
  rows += '<li><b>Need-Based Scholarship:</b> ' + (u.need_based_scholarship || 'N/A') + '</li>';
  rows += '<li><b>Merit-Based Scholarship:</b> ' + (u.merit_based_scholarship || 'N/A') + '</li>';
  rows += '<li><b>International Financial Aid:</b> ' + (u.international_financial_aid || 'N/A') + '</li>';
  rows += '<li><b>How to Win the Best Scholarships:</b> ' + (u.scholarship_tips || 'N/A') + '</li>';
  rows += '<li><b>Estimated Out-of-Pocket (after aid):</b> ' + (u.estimated_out_of_pocket || 'N/A') + '</li>';
  rows += '<li><b>Required Bank Balance / Financial Proof:</b> ' + (u.required_bank_balance || 'N/A') + '</li>';
  const visaQA = Array.isArray(u.university_specific_visa_prep) ? u.university_specific_visa_prep : [];
  if (visaQA.length) {
    rows += '<li><b>Visa interview — questions specific to this university:</b><ul>';
    for (let q = 0; q < visaQA.length; q++) {
      rows += '<li><i>Q: ' + (visaQA[q].question || '') + '</i><br>A: ' + (visaQA[q].sample_answer || '') + '</li>';
    }
    rows += '</ul></li>';
  }
  if (u.source_url) { rows += '<li><b>Source:</b> <a href="' + u.source_url + '">' + u.source_url + '</a> (' + (u.data_confidence || 'confirm on official site') + ')</li>'; }
  rows += '</ul>';
}
if (!rows) { rows = '<p>We could not find strong matches automatically. Our counseling team will review your profile and follow up personally, free of charge.</p>'; }
function textToHtml(t) {
  if (!t) return '<p>Our team will share this with you shortly.</p>';
  var parts = String(t).split(String.fromCharCode(10) + String.fromCharCode(10));
  var out = '';
  for (var p = 0; p < parts.length; p++) {
    out += '<p>' + parts[p].split(String.fromCharCode(10)).join('<br>') + '</p>';
  }
  return out;
}
let html = '<p>Dear ' + (form['Full Name'] || 'Student') + ',</p>';
html += '<p>This is a completely free service — no consultancy fees, ever. Based on your profile, here is your personalised shortlist of US universities for <b>' + (form['Target Program'] || 'your target program') + '</b>, ordered best-first — the most affordable options with the highest scholarships and financial aid appear at the top. University facts below come from official US Government (College Scorecard) data.</p>';
if (agentOut.overall_target_bank_balance) {
  html += '<p style="padding:10px;background:#f2f7ff;border-left:4px solid #2b6cb0;"><b>Your target bank balance:</b> ' + agentOut.overall_target_bank_balance + '</p>';
}
if (agentOut.recommendation_summary) {
  html += textToHtml(agentOut.recommendation_summary);
}
html += '<h2>1. Your Matched Universities (best-first)</h2>';
html += rows;
html += '<h2>2. How to Apply — Step by Step</h2>';
html += textToHtml(agentOut.application_guide);
html += '<h2>3. US Student Visa (F-1) — Complete Guide</h2>';
html += textToHtml(agentOut.visa_guide);
html += '<h2>4. Visa Interview Preparation (General)</h2>';
html += textToHtml(agentOut.visa_interview_prep);
html += '<h2>Your Next Steps</h2>';
html += '<ol>';
html += '<li>Review each university deadline and admission requirement.</li>';
html += '<li>Prepare your financial documents, including the required bank statement.</li>';
html += '<li>Follow the application guide above to submit your applications.</li>';
html += '<li>Once admitted, follow the visa guide and interview preparation, including the university-specific questions above.</li>';
html += '<li>Reply to this email to book a free counseling session with our team.</li>';
html += '</ol>';
html += '<p style="font-size:12px;color:#666;border-top:1px solid #ddd;padding-top:8px;"><b>Important:</b> Deadlines, tuition, and scholarship amounts change every year. Please always confirm the figures above on each university\'s official website and on the official US government sites (studyinthestates.dhs.gov and travel.state.gov) before making any decision or payment.</p>';
html += '<p>Best regards,<br>US University Education Consultancy</p>';
return [{ json: { summary_html: html, student_email: form['Email'] || '', student_name: form['Full Name'] || '', match_count: unis.length } }];
